def handle_top_customers(self, limit: Any) -> Response:
    try:
        limit_int = require_positive_int(limit, "limit")
    except InvalidRequest as exc:
        return bad_request(exc)
    customers = self._customers.list_all()
    customer_values = []
    for customer in customers:
        try:
            orders = self._service.list_for_customer(customer.customer_id)
        except CustomerNotFound:
            orders = []
        non_cancelled = [order for order in orders if order.status != "cancelled"]
        lifetime_value_cents = sum(self._service.summarize(order).total_cents for order in non_cancelled)
        if lifetime_value_cents > 0:
            customer_values.append({
                "customer_id": customer.customer_id,
                "name": customer.name,
                "lifetime_value_cents": lifetime_value_cents,
            })
    customer_values.sort(key=lambda x: (-x["lifetime_value_cents"], x["customer_id"]))
    return Response(200, {"customers": customer_values[:limit_int]})

